import json
with open('/app/resources/treasury_bulletin_1994_03.json') as f:
    data = json.load(f)

# Check if there's a 'data' key or similar
def find_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(f'{path}.{k}' if path else k)
            if isinstance(v, (dict, list)):
                find_keys(v, f'{path}.{k}' if path else k)
    elif isinstance(obj, list) and len(obj) > 0:
        print(f'{path}: list of {len(obj)} items')
        find_keys(obj[0], path + '[0]')

